<script lang="ts">import {onMount} from 'svelte';import AppHeader from '$lib/components/common/AppHeader.svelte';import Charts from '$lib/components/stats/Charts.svelte';import {statsApi} from '$lib/api';import type {Stats} from '$lib/types';let range='all';let stats:Stats|null=null;let loading=true;let error='';async function load(){loading=true;error='';try{stats=await statsApi.overview(range)}catch(e){error=e instanceof Error?e.message:'Could not load statistics'}finally{loading=false}}onMount(load);const money=(x:string)=>`${Number(x)>=0?'+':''}$${Number(x).toFixed(2)}`;</script>
<svelte:head><title>Statistics · Trade Track</title></svelte:head><main class="shell"><AppHeader title="Statistics" subtitle="Find the patterns behind your results"/><div class="ranges">{#each [['7d','7D'],['1m','1M'],['3m','3M'],['all','ALL']] as r}<button class:active={range===r[0]} onclick={()=>{range=r[0];load()}}>{r[1]}</button>{/each}</div>{#if error}<p class="error">{error}</p>{:else if loading}<div class="empty">Calculating your edge…</div>{:else if stats}<section class="grid metrics"><div class="card"><small>Net P&amp;L</small><strong class:profit={Number(stats.net_pnl)>=0} class:loss={Number(stats.net_pnl)<0}>{money(stats.net_pnl)}</strong></div><div class="card"><small>Win rate</small><strong>{stats.win_rate}%</strong></div><div class="card"><small>Profit factor</small><strong>{stats.profit_factor===null?'∞':stats.profit_factor}</strong></div><div class="card"><small>Average win</small><strong class="profit">{money(stats.average_win)}</strong></div><div class="card"><small>Average loss</small><strong class="loss">{money(stats.average_loss)}</strong></div><div class="card"><small>Total trades</small><strong>{stats.total_trades}</strong></div></section>{#if stats.total_trades}<Charts {stats}/>{:else}<div class="card empty"><h2>No closed trades in this range</h2><p>Charts will appear as your journal grows.</p></div>{/if}{/if}</main>
<style>.ranges{display:flex;gap:6px;margin-bottom:16px}.ranges button{background:#0d192b;border:1px solid #1c2b42;color:#8290a7;border-radius:10px;padding:8px 14px;cursor:pointer}.ranges .active{background:#2474ff;color:white;border-color:#2474ff}.metrics{grid-template-columns:repeat(3,1fr);margin-bottom:14px}.metrics .card{display:grid;gap:8px}.metrics small{color:#8290a7}.metrics strong{font-size:1.25rem}@media(max-width:600px){.metrics{grid-template-columns:repeat(2,1fr)}}</style>
